// Transforma a resposta paginada/listada do CRM em um item por atendimento.
// O loop nativo processa cada item depois; aqui nao decidimos envio.
const respostas = $('Buscar atendimentos no CRM').all();
const itens = respostas.flatMap((resposta) => {
  const json = resposta.json ?? {};
  if (Array.isArray(json)) return json;
  return json.atendimentos ?? json.content ?? json.data ?? json.items ?? [json];
});
const controle = $('Preparar regras para execucao').first().json;
const modoTesteExclusivo = controle.modo_teste_exclusivo === true;
const leadIdTeste = String(controle.lead_id_teste_followup_inativo ?? '').trim();

return itens
  .filter((cartao) => {
    if (!cartao || !(cartao.atendimentoId || cartao.id)) return false;
    const leadId = String(cartao.leadId ?? cartao.lead?.id ?? '');
    return !modoTesteExclusivo || leadId === leadIdTeste;
  })
  .map((cartao, indice) => ({
    json: {
      indice_atendimento: indice,
      atendimento_id: String(cartao.atendimentoId ?? cartao.id ?? ''),
      lead_id: String(cartao.leadId ?? cartao.lead?.id ?? ''),
      lead_nome: String(cartao.leadNome ?? cartao.lead?.nome ?? cartao.nomeLead ?? cartao.contatoNome ?? ''),
      status_atendimento: String(cartao.status ?? '').toUpperCase(),
      atendente_id: String(cartao.atendenteId ?? ''),
      atendente_nome: String(cartao.atendenteNome ?? ''),
      ultima_mensagem_preview: String(cartao.ultimaMensagemPreview ?? ''),
      ultima_mensagem_remetente_tipo: String(cartao.ultimaMensagemRemetenteTipo ?? '').toUpperCase(),
      ultima_mensagem_em: String(cartao.ultimaMensagemEm ?? cartao.updatedAt ?? ''),
      ultima_mensagem_do_lead_em: String(cartao.ultimaMensagemDoLeadEm ?? ''),
      nao_lidas: Number(cartao.naoLidas ?? 0)
    }
  }));

// Confirma o resultado do envio sem expor credenciais.
const envio = $('Enviar follow-up pela Meta').item.json;
const registro = $('Registrar follow-up no CRM').item.json;
const registroLocal = $('Registrar envio anti-repeticao').item.json;
const atendimento = $('Aplicar trava anti-repeticao').item.json;

return [{
  json: {
    codigo: 'FOLLOWUP_ENVIADO',
    atendimento_id: atendimento.atendimento_id,
    lead_id: atendimento.lead_id,
    regra_followup_id: atendimento.regra_followup_id,
    regra_followup_nome: atendimento.regra_followup_nome,
    regra_tempo_minutos: atendimento.regra_tempo_minutos,
    minutos_sem_resposta: atendimento.minutos_sem_resposta,
    whatsapp_message_id: String(envio.messages?.[0]?.id ?? ''),
    mensagem_crm_id: String(registro.mensagemId ?? ''),
    registro_local_id: String(registroLocal.id ?? ''),
    registro_local_enviado_em: String(registroLocal.enviado_em ?? ''),
    crm_idempotente: Boolean(registro.idempotente)
  }
}];

// Avalia um unico atendimento contra as regras ativas retornadas pelo CRM.
// Regra corrigida:
// 1. Elegibilidade conta desde a ultima mensagem nossa/atendente.
// 2. Anti-repeticao ancora na ultima mensagem do cliente, para follow-up nao gerar outro follow-up.
// 3. Sem mensagem do cliente ou fora da janela de texto livre da Meta, nao envia texto comum.
const atendimento = $('Loop follow-ups').item.json;
const variaveis = $('Variaveis follow-up').first().json;
const regrasBrutas = $('Preparar regras para execucao').all().flatMap((item) => {
  const json = item.json ?? {};
  if (Array.isArray(json)) return json;
  return json.regras ?? json.content ?? json.data ?? json.items ?? [json];
});
const regras = regrasBrutas
  .map((regra) => ({
    id: String(regra.id ?? ''),
    nome: String(regra.nome ?? ''),
    tempoMinutos: Number(regra.tempoMinutos ?? regra.tempo_minutos ?? 0),
    texto: String(regra.texto ?? regra.mensagem ?? '').trim()
  }))
  .filter((regra) => regra.id && regra.tempoMinutos > 0 && regra.texto)
  .sort((a, b) => a.tempoMinutos - b.tempoMinutos);

const normalizarTexto = (valor) => String(valor ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const status = String(atendimento.status_atendimento ?? '').toUpperCase();
const statusBloqueados = String(variaveis.status_bloqueados_followup ?? '').split(',').map((item) => item.trim().toUpperCase()).filter(Boolean);
const statusPermitido = Boolean(status) && !statusBloqueados.includes(status);
const remetente = String(atendimento.ultima_mensagem_remetente_tipo ?? '').toUpperCase();
const ultimaFoiNossa = Boolean(remetente) && remetente !== 'LEAD';
const ultimaMensagemBaseTexto = String(atendimento.ultima_mensagem_em ?? '').trim();
const ultimaMensagemBaseMs = Date.parse(ultimaMensagemBaseTexto);
const ultimaMensagemLeadTexto = String(atendimento.ultima_mensagem_do_lead_em ?? '').trim();
const ultimaMensagemLeadMs = Date.parse(ultimaMensagemLeadTexto);
const textoUltimaMensagem = normalizarTexto(atendimento.ultima_mensagem_preview);
const textosFollowup = new Set(regras.map((regra) => normalizarTexto(regra.texto)).filter(Boolean));
const ultimaMensagemEhFollowup = Boolean(textoUltimaMensagem && textosFollowup.has(textoUltimaMensagem));
const minutosSemResposta = ultimaFoiNossa && Number.isFinite(ultimaMensagemBaseMs)
  ? Math.floor((Date.now() - ultimaMensagemBaseMs) / 60000)
  : 0;
const minutosDesdeLead = Number.isFinite(ultimaMensagemLeadMs)
  ? Math.floor((Date.now() - ultimaMensagemLeadMs) / 60000)
  : null;
const janelaTextoLivreMinutos = Number(variaveis.janela_texto_livre_minutos ?? 1430);
const janelaTextoLivreAberta = Number.isFinite(minutosDesdeLead) && minutosDesdeLead <= janelaTextoLivreMinutos;
const regrasVencidas = regras.filter((regra) => minutosSemResposta >= regra.tempoMinutos);

let motivo = 'ELEGIVEL';
if (regras.length === 0) motivo = 'SEM_REGRAS_ATIVAS';
else if (!atendimento.atendimento_id || !atendimento.lead_id) motivo = 'SEM_ATENDIMENTO_OU_LEAD';
else if (!statusPermitido) motivo = 'STATUS_FINALIZADO_OU_INVALIDO';
else if (!remetente) motivo = 'REMETENTE_ULTIMA_MENSAGEM_AUSENTE';
else if (!ultimaFoiNossa) motivo = 'ULTIMA_MENSAGEM_DO_LEAD';
else if (ultimaMensagemEhFollowup) motivo = 'ULTIMA_MENSAGEM_JA_E_FOLLOWUP';
else if (!Number.isFinite(ultimaMensagemBaseMs)) motivo = 'DATA_ULTIMA_MENSAGEM_INVALIDA';
else if (!Number.isFinite(ultimaMensagemLeadMs)) motivo = 'SEM_MENSAGEM_DO_LEAD';
else if (!janelaTextoLivreAberta) motivo = 'JANELA_24H_FECHADA_SEM_TEMPLATE';
else if (regrasVencidas.length === 0) motivo = 'TEMPO_INSUFICIENTE';

const enviarFollowup = motivo === 'ELEGIVEL';
return [{
  json: {
    ...atendimento,
    status_bloqueados_followup: statusBloqueados,
    minutos_sem_resposta: minutosSemResposta,
    minutos_desde_ultima_mensagem_lead: minutosDesdeLead,
    janela_texto_livre_aberta: janelaTextoLivreAberta,
    ultima_mensagem_eh_followup: ultimaMensagemEhFollowup,
    followup_ciclo_chave: ultimaMensagemLeadTexto,
    regras_vencidas: regrasVencidas,
    regra_followup_id: '',
    regra_followup_nome: '',
    regra_tempo_minutos: null,
    texto_followup: '',
    motivo_followup: motivo,
    enviar_followup: enviarFollowup
  }
}];

// Escolhe a proxima regra vencida que ainda nao foi enviada neste ciclo.
// O ciclo muda quando o lead responde. Follow-up enviado nao abre novo ciclo.
const atendimento = $('Avaliar follow-up por regra').item.json;
const variaveis = $('Variaveis follow-up').first().json;
const historico = $('Verificar follow-ups ja enviados no ciclo').item.json;
const enviadosRaw = historico.followups_enviados ?? [];
const enviadosLista = Array.isArray(enviadosRaw)
  ? enviadosRaw.map(String)
  : String(enviadosRaw).replace(/[{}]/g, '').split(',').filter(Boolean);
const enviados = new Set(enviadosLista);
const regrasVencidas = Array.isArray(atendimento.regras_vencidas) ? atendimento.regras_vencidas : [];
const regra = regrasVencidas.find((item) => !enviados.has(String(item.id)));
const nomeLead = String(atendimento.lead_nome ?? '').trim();
const nomePadrao = String(variaveis.nome_padrao_followup ?? '').trim();
if (!nomePadrao) throw new Error('NOME_PADRAO_FOLLOWUP_NAO_CONFIGURADO');
const aplicarVariaveis = (texto) => String(texto ?? '')
  .replace(/\{nome\}/gi, nomeLead || nomePadrao);

let motivo = String(atendimento.motivo_followup ?? '');
let enviar = Boolean(atendimento.enviar_followup);
if (enviar && !regra) {
  motivo = 'FOLLOWUPS_JA_ENVIADOS_SEM_RESPOSTA';
  enviar = false;
}

return [{
  json: {
    ...atendimento,
    followups_enviados_no_ciclo: [...enviados],
    total_followups_enviados_sem_resposta: enviados.size,
    regra_followup_id: regra?.id ?? '',
    regra_followup_nome: regra?.nome ?? '',
    regra_tempo_minutos: regra?.tempoMinutos ?? null,
    texto_followup: regra ? aplicarVariaveis(regra.texto) : '',
    texto_followup_original: regra?.texto ?? '',
    variaveis_followup: {
      nome: nomeLead || nomePadrao
    },
    motivo_followup: motivo,
    enviar_followup: enviar
  }
}];

// Atualiza a reserva local depois que a Meta aceitou o envio.
// A gravacao como ENVIADO acontece antes do registro no CRM para evitar duplicidade se o CRM falhar.
const atendimento = $('Aplicar trava anti-repeticao').item.json;
const variaveis = $('Variaveis follow-up').first().json;
const statusEnviado = String(variaveis.status_enviado_followup ?? '').trim();
const leadChavePadrao = String(variaveis.lead_ultima_mensagem_chave_padrao ?? '').trim();
const envio = $('Enviar follow-up pela Meta').item.json;
const sqlText = (valor) => String(valor ?? '').replace(/'/g, "''");
const leadChave = String(atendimento.lead_ultima_mensagem_chave || atendimento.ultima_mensagem_do_lead_em || leadChavePadrao);
const whatsappId = String(envio.messages?.[0]?.id ?? '');
const linhas = [
  'UPDATE public.follow_ups_temporary',
  'SET',
  "  whatsapp_message_id = '" + sqlText(whatsappId) + "',",
  "  mensagem_enviada = '" + sqlText(atendimento.texto_followup) + "',",
  "  status = '" + sqlText(statusEnviado) + "',",
  '  enviado_em = now(),',
  '  updated_at = now()',
  "WHERE crm_atendimento_id = '" + sqlText(atendimento.atendimento_id) + "'",
  "  AND follow_up_config_id = '" + sqlText(atendimento.regra_followup_id) + "'",
  "  AND lead_ultima_mensagem_chave = '" + sqlText(leadChave) + "'",
  'RETURNING id, enviado_em, status;'
];
return [{ json: { ...atendimento, sql_registro_followup: linhas.join(String.fromCharCode(10)) } }];

// Reserva a chave de follow-up antes do envio pela Meta.
// A chave anti-repeticao e a ultima mensagem do lead; a base do relogio continua sendo a ultima mensagem nossa.
const atendimento = $('Aplicar trava anti-repeticao').item.json;
const variaveis = $('Variaveis follow-up').first().json;
const statusReservado = String(variaveis.status_reservado_followup ?? '').trim();
const leadChavePadrao = String(variaveis.lead_ultima_mensagem_chave_padrao ?? '').trim();
const tituloPadrao = String(variaveis.titulo_followup_padrao ?? '').trim();
const reservaExpiraMinutos = Number(variaveis.reserva_expira_minutos);
if (!Number.isFinite(reservaExpiraMinutos) || reservaExpiraMinutos <= 0) throw new Error('RESERVA_EXPIRA_MINUTOS_INVALIDO');
const sqlText = (valor) => String(valor ?? '').replace(/'/g, "''");
const sqlTimestamp = (valor) => {
  const texto = String(valor ?? '').trim();
  return texto ? "'" + sqlText(texto) + "'::timestamptz" : 'NULL';
};
const leadUltima = String(atendimento.ultima_mensagem_do_lead_em ?? '').trim();
const baseUltima = String(atendimento.ultima_mensagem_em ?? '').trim();
const leadChave = String(atendimento.followup_ciclo_chave || leadUltima || leadChavePadrao);
const titulo = atendimento.regra_followup_nome || tituloPadrao;
const linhas = [
  'WITH tentativa AS (',
  '  INSERT INTO public.follow_ups_temporary (',
  '    follow_up_config_id, clinica_id, paciente_id, lead_id, titulo, scheduled_at, crm_atendimento_id, crm_paciente_id,',
  '    regra_followup_nome, lead_ultima_mensagem_em, lead_ultima_mensagem_chave, ultima_mensagem_base_em,',
  '    mensagem_enviada, status, enviado_em, updated_at',
  '  ) VALUES (',
  "    '" + sqlText(atendimento.regra_followup_id) + "',",
  '    1,',
  "    '" + sqlText(atendimento.lead_id) + "',",
  "    '" + sqlText(atendimento.lead_id) + "',",
  "    '" + sqlText(titulo) + "',",
  '    now(),',
  "    '" + sqlText(atendimento.atendimento_id) + "',",
  "    '" + sqlText(atendimento.lead_id) + "',",
  "    '" + sqlText(atendimento.regra_followup_nome) + "',",
  '    ' + sqlTimestamp(leadUltima) + ',',
  "    '" + sqlText(leadChave) + "',",
  '    ' + sqlTimestamp(baseUltima) + ',',
  "    '" + sqlText(atendimento.texto_followup) + "',",
  "    '" + sqlText(statusReservado) + "', NULL, now()",
  '  )',
  '  ON CONFLICT (crm_atendimento_id, follow_up_config_id, lead_ultima_mensagem_chave)',
  '  DO UPDATE SET',
  "    status = '" + sqlText(statusReservado) + "',",
  '    mensagem_enviada = EXCLUDED.mensagem_enviada,',
  '    ultima_mensagem_base_em = EXCLUDED.ultima_mensagem_base_em,',
  '    updated_at = now()',
  "  WHERE public.follow_ups_temporary.status = '" + sqlText(statusReservado) + "'",
  "    AND public.follow_ups_temporary.updated_at < now() - interval '" + reservaExpiraMinutos + " minutes'",
  '  RETURNING id, status, updated_at',
  ')',
  'SELECT',
  '  EXISTS(SELECT 1 FROM tentativa) AS reserva_criada,',
  '  (SELECT id FROM tentativa LIMIT 1) AS id,',
  '  (SELECT status FROM tentativa LIMIT 1) AS status,',
  '  (SELECT updated_at FROM tentativa LIMIT 1) AS reservado_em;'
];
return [{ json: { ...atendimento, lead_ultima_mensagem_chave: leadChave, sql_reserva_followup: linhas.join(String.fromCharCode(10)) } }];

