// Mantem as regras do CRM quando o recurso geral esta ativo.
// Quando o CRM devolve vazio, cria uma unica regra local e marca a execucao como teste exclusivo.
// O filtro pelo lead acontece no proximo node, antes do loop.
const variaveis = $('Variaveis follow-up').first().json;
const respostas = $('Buscar regras de follow-up').all();
const bruto = respostas.flatMap((item) => {
  const json = item.json ?? {};
  if (Array.isArray(json)) return json;
  return json.regras ?? json.content ?? json.data ?? json.items ?? [json];
});
const regras = bruto
  .map((regra) => ({
    id: String(regra.id ?? ''),
    nome: String(regra.nome ?? ''),
    tempoMinutos: Number(regra.tempoMinutos ?? regra.tempo_minutos ?? 0),
    texto: String(regra.texto ?? regra.mensagem ?? '').trim()
  }))
  .filter((regra) => regra.id && regra.tempoMinutos > 0 && regra.texto);

if (regras.length > 0) {
  return [{ json: { regras, modo_teste_exclusivo: false, origem_regras: 'CRM' } }];
}

const leadIdTeste = String(variaveis.lead_id_teste_followup_inativo ?? '').trim();
if (!leadIdTeste) throw new Error('LEAD_ID_TESTE_FOLLOWUP_INATIVO_NAO_CONFIGURADO');
const regraTeste = {
  id: String(variaveis.regra_teste_followup_inativo_id ?? '').trim(),
  nome: String(variaveis.regra_teste_followup_inativo_nome ?? '').trim(),
  tempoMinutos: Number(variaveis.regra_teste_followup_inativo_tempo_minutos ?? 0),
  texto: String(variaveis.regra_teste_followup_inativo_texto ?? '').trim()
};
if (!regraTeste.id || !regraTeste.nome || !Number.isFinite(regraTeste.tempoMinutos) || regraTeste.tempoMinutos <= 0 || !regraTeste.texto) {
  throw new Error('REGRA_TESTE_FOLLOWUP_INATIVO_INVALIDA');
}
return [{ json: {
  regras: [regraTeste],
  modo_teste_exclusivo: true,
  lead_id_teste_followup_inativo: leadIdTeste,
  origem_regras: 'TESTE_COM_FOLLOWUP_GERAL_INATIVO'
} }];
